function stats(items){return `<div class="stats-grid">${items.map(([ico,label,val,note])=>`<article class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${ico}</span></div><div class="stat-value">${val}</div><div class="stat-note">${note}</div></article>`).join('')}</div>`}
function churchRows(){let list=role==='pastor'?[churches[0]]:churches;return `<div class="church-list">${list.map((c,i)=>`<div class="church-row"><div class="church-emblem">⌂</div><div><b>${c[0]}</b><small>${c[1]}</small></div><div class="row-end"><b>${c[3]}</b><small>${t('membersLabel')}</small></div><button class="text-link" data-church="${i}">→</button></div>`).join('')}</div>`}
function activityRows(){return `<div class="activity"><div class="activity-row"><div class="activity-dot">＋</div><div><b>${lang==='es'?'Nuevo miembro registrado':'New member registered'}</b><small>Iglesia Central · María Fernanda Gómez</small></div><time>09:42</time></div><div class="activity-row"><div class="activity-dot">◈</div><div><b>${lang==='es'?'Informe mensual enviado':'Monthly report submitted'}</b><small>Iglesia Betania · ${lang==='es'?'Finanzas':'Finance'}</small></div><time>Ayer</time></div><div class="activity-row"><div class="activity-dot">✧</div><div><b>${lang==='es'?'Matrículas ITAIC actualizadas':'ITAIC enrollment updated'}</b><small>${lang==='es'?'Instituto teológico':'Theological institute'} · 3 ${lang==='es'?'estudiantes':'students'}</small></div><time>12 jun</time></div></div>`}
function dashboard(){let pastor=role==='pastor',secret=role==='secretario';let s=stats([[ '⌂',t('totalChurches'),pastor?'1':'12',lang==='es'?'en el circuito':'in circuit'],['♙',t('totalMembers'),pastor?'128':'1,246',`<span class="positive">↑ 4.8%</span> ${lang==='es'?'este año':'this year'}`],['✧',t('baptized'),pastor?'96':'918',lang==='es'?'73.6% del total':'73.6% of total'],['◈',t('monthlyIncome'),pastor?'$2.450.000':'$18.640.000',t('thisMonth')]]);if(secret)s=stats([['♙',t('totalMembers'),'1,246',t('registered')],['✧',t('baptized'),'918','73.6%'],['♀',t('women'),'698',lang==='es'?'56% del total':'56% of total'],['♧',t('children'),'184',lang==='es'?'menores de 13 años':'under 13 years']]);return `${pageHead(`${t('hello')}, ${roles[role][lang]} 👋`,lang==='es'?'Aquí tienes el resumen de actividad del circuito.':'Here is the circuit activity overview.')} ${s}<div class="grid-2"><section class="panel"><div class="panel-head"><div><h2>${t('churchOverview')}</h2><p>${t('dateRange')}</p></div>${role==='presbitero'?`<button class="text-link" data-go="churches">${t('viewAll')} →</button>`:''}</div>${churchRows()}</section><section class="panel"><div class="panel-head"><div><h2>${t('recentActivity')}</h2><p>${lang==='es'?'Últimos movimientos del circuito':'Latest circuit activity'}</p></div></div>${activityRows()}</section></div>`}
function churchPage(){return `${pageHead(t('churches'),t('churchesSubtitle'),`<button class="primary" data-modal="church">＋ ${t('newChurch')}</button>`)}<section class="panel"><div class="panel-head"><div><h2>${t('churchOverview')}</h2><p>${churches.length} ${t('churches').toLowerCase()} · ${t('dateRange')}</p></div><button class="secondary" data-export="churches">${t('generate')} →</button></div>${churchRows()}</section>`}
function financePage(){let totalIn=2450000+612000+455000,totalOut=1130000+302000+221000;return `${pageHead(t('finance'),role==='pastor'?t('financeSubtitlePastor'):t('financeSubtitle'),`<button class="primary" data-do="report">${t('generate')} →</button>`)}<div class="summary-band"><div><small>${t('initial')}</small><b>$8.420.000</b></div><div><small>${t('income')}</small><b>$${totalIn.toLocaleString('es-CO')}</b></div><div><small>${t('expenses')}</small><b>$${totalOut.toLocaleString('es-CO')}</b></div></div><section class="panel"><div class="panel-head"><div><h2>${t('monthlyReport')} · ${selectedYear}</h2><p>${role==='pastor'?'Iglesia Central':t('allChurches')}</p></div><span class="status ${role==='pastor'?'pending':''}">${role==='pastor'?t('pending'):t('closed')}</span></div><div class="table-card"><table class="data-table"><thead><tr><th>${t('churchLabel')}</th><th>${t('initial')}</th><th>${t('income')}</th><th>${t('expenses')}</th><th>${t('final')}</th><th>${t('status')}</th></tr></thead><tbody>${(role==='pastor'?[churches[0]]:churches).map((c,i)=>`<tr><td><strong>${c[0]}</strong></td><td>$${(1800000+i*380000).toLocaleString('es-CO')}</td><td class="amount">$${(2450000-i*260000).toLocaleString('es-CO')}</td><td>$${(1130000-i*110000).toLocaleString('es-CO')}</td><td><strong>$${(3120000+i*230000).toLocaleString('es-CO')}</strong></td><td><span class="status ${i===3&&role!=='pastor'?'pending':''}">${i===3&&role!=='pastor'?t('pending'):t('closed')}</span></td></tr>`).join('')}</tbody></table></div>${role==='pastor'?`<div class="head-actions" style="justify-content:flex-end;margin-top:15px"><button class="secondary" data-modal="movement">＋ ${t('addMovement')}</button><button class="primary" data-do="close">${t('closePeriod')} →</button></div>`:''}</section><section class="panel"><div class="panel-head"><div><h2>${t('recentActivity')}</h2><p>Iglesia Central</p></div></div><div class="table-card"><table class="data-table"><thead><tr><th>${t('date')}</th><th>${t('description')}</th><th>${t('income')} / ${t('expenses')}</th><th>${t('amount')}</th></tr></thead><tbody>${(finance.length?finance:[{date:'2026-06-01',description:lang==='es'?'Diezmos del domingo':'Sunday tithes',type:t('income'),amount:2450000},{date:'2026-06-04',description:lang==='es'?'Servicios públicos':'Utilities',type:t('expenses'),amount:320000}]).map(m=>`<tr><td>${m.date}</td><td>${m.description}</td><td>${m.type||t('income')}</td><td class="amount">$${Number(m.amount).toLocaleString('es-CO')}</td></tr>`).join('')}</tbody></table></div></section>`}
function memberRows(){let data=members.filter(m=>`${m.name} ${m.id}`.toLowerCase().includes(filter.toLowerCase()));return data.map(m=>`<tr><td><div class="person-cell"><span class="mini-avatar">${m.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><strong>${m.name}</strong></div></td><td>${m.id}</td><td>${m.age}</td><td>${m.sex}</td><td>${m.civil}</td><td><span class="status ${m.baptized?'':'pending'}">${m.baptized?t('yes'):t('no')}</span></td><td><button class="inline-actions" data-edit-member="${m.id}">⋯</button></td></tr>`).join('')||`<tr><td colspan="7" class="empty">${t('empty')}</td></tr>`}
function secretaryPage(){let baptized=members.filter(m=>m.baptized).length,women=members.filter(m=>m.sex==='Femenino').length,children=members.filter(m=>m.age<13).length;return `${pageHead(t('secretary'),t('secretarySubtitle'),`<button class="primary" data-do="report">${t('generate')} →</button>`)}${stats([['♙',t('totalMembers'),role==='pastor'?members.length:'1,246',t('registered')],['✧',t('baptized'),role==='pastor'?baptized:'918',`${role==='pastor'?Math.round(baptized/Math.max(1,members.length)*100):74}%`],['♀',t('women'),role==='pastor'?women:'698',t('women')],['♧',t('children'),role==='pastor'?children:'184',lang==='es'?'menores de 13 años':'under 13 years']])}<section class="table-card"><div class="table-tools"><div class="search"><input id="memberSearch" placeholder="${t('search')}" value="${filter}"></div><select class="filter"><option>${t('allChurches')}</option>${churches.map(c=>`<option>${c[0]}</option>`).join('')}</select>${role==='pastor'?`<button class="primary" data-modal="member">＋ ${t('addMember')}</button>`:''}</div><table class="data-table"><thead><tr><th>${t('member')}</th><th>${t('document')}</th><th>${t('age')}</th><th>${t('sex')}</th><th>${t('civil')}</th><th>${t('baptism')}</th><th></th></tr></thead><tbody id="memberRows">${memberRows()}</tbody></table><div class="table-foot">${members.length} ${t('registered').toLowerCase()}</div></section>`}
function simplePage(which){let title=t(which),sub=t(which+'Subtitle')||t('itaicSubtitle'),students=which==='itaic';return `${pageHead(title,sub,students?`<button class="secondary" data-export="students">${t('generate')} →</button>`:`<button class="primary" data-modal="pastor">＋ ${t('newPastor')}</button>`)}${students?`<div class="stats-grid">${[['▣',t('students'),'48',lang==='es'?'matriculados actualmente':'currently enrolled'],['⌂',t('campuses'),'4',lang==='es'?'sedes activas':'active campuses'],['♙',t('teachersTitle'),'12',lang==='es'?'maestros asignados':'assigned teachers'],['✧',t('churches'),'9',lang==='es'?'iglesias participantes':'participating churches']].map(a=>`<article class="stat-card"><div class="stat-top"><span>${a[1]}</span><span class="stat-icon">${a[0]}</span></div><div class="stat-value">${a[2]}</div><div class="stat-note">${a[3]}</div></article>`).join('')}</div><div class="toolbar" style="margin-bottom:16px"><button class="secondary">${t('all')} · 48</button><button class="secondary">${t('year1')} · 19</button><button class="secondary">${t('year2')} · 16</button><button class="secondary">${t('year3')} · 13</button><button class="secondary">⌄ ${t('churchLabel')}</button><button class="secondary">⌄ ${t('campuses')}</button></div><div class="grid-2">${[['Primer año','19','Sede Central'],['Segundo año','16','Sede Betania'],['Tercer año','13','Sede Central']].map(a=>`<section class="panel"><div class="panel-head"><div><h2>${lang==='en'?({ 'Primer año':'First year','Segundo año':'Second year','Tercer año':'Third year'}[a[0]]):a[0]}</h2><p>${a[1]} ${t('students').toLowerCase()} · ${a[2]}</p></div><button class="text-link">${t('viewAll')} →</button></div><div class="church-row"><div class="church-emblem">♙</div><div><b>${a[0]==='Primer año'?'María Gómez':a[0]==='Segundo año'?'José Torres':'Lucía Díaz'}</b><small>Iglesia Central</small></div><div class="row-end"><b>4.6</b><small>${t('grades')}</small></div></div><div class="church-row"><div class="church-emblem">♙</div><div><b>${a[0]==='Primer año'?'David López':'Ana Martínez'}</b><small>Iglesia Betania</small></div><div class="row-end"><b>4.2</b><small>${t('grades')}</small></div></div></section>`).join('')}</div><section class="panel"><div class="panel-head"><div><h2>${t('teachersTitle')}</h2><p>${lang==='es'?'Maestros asignados por sede y año':'Teachers assigned by campus and year'}</p></div><button class="secondary" data-modal="teacher">＋ ${t('teachers')}</button></div><div class="church-row"><div class="church-emblem">♙</div><div><b>Pr. José Martínez</b><small>Sede Central · ${t('year1')} y ${t('year2')}</small></div></div><div class="church-row"><div class="church-emblem">♙</div><div><b>Ana Lucía Ríos</b><small>Sede Betania · ${t('year3')}</small></div></div></section>`:`<section class="panel"><div class="panel-head"><div><h2>${t('pastors')}</h2><p>4 ${t('pastors').toLowerCase()} · Circuito Córdoba</p></div></div>${churches.map(c=>`<div class="church-row"><div class="church-emblem">♙</div><div><b>${c[2]}</b><small>${c[0]} · ${lang==='es'?'Preparación: Instituto bíblico':'Education: Bible institute'}</small></div><button class="text-link">⋯</button></div>`).join('')}</section>`}`}
