function baseBindPage(){document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$$('[data-go]').forEach(b=>b.onclick=()=>{page=b.dataset.go;renderNav();renderPage()});$$('[data-modal]').forEach(b=>b.onclick=()=>openModal(b.dataset.modal));$$('[data-export]').forEach(b=>b.onclick=()=>exportData(b.dataset.export));$$('[data-do="report"]').forEach(b=>b.onclick=()=>{notify(t('reportReady'));print()});$$('[data-do="close"]').forEach(b=>b.onclick=()=>{notify(t('periodClosed'));b.textContent='✓ '+t('periodClosed');b.disabled=true});$$('[data-church]').forEach(b=>b.onclick=()=>{let c=churches[Number(b.dataset.church)];page='churches';$('#content').innerHTML=`${pageHead(c[0],t('churchDetail'))}${stats([['♙',t('totalMembers'),c[3],t('registered')],['✧',t('baptized'),'96','75%'],['◈',t('balance'),'$3.120.000',t('thisMonth')],['♙',t('pastorLabel'),c[2],'']])}<section class="panel"><div class="panel-head"><h2>${c[0]}</h2><span class="status">${t('active')}</span></div><p>${t('address')}: ${c[1]}</p><p>${t('pastorLabel')}: ${c[2]}</p><button class="secondary" data-go="secretary">${t('members')} →</button></section>`;bindPage()});let search=$('#memberSearch');if(search)search.oninput=()=>{filter=search.value;$('#memberRows').innerHTML=memberRows()}}
function baseOpenModal(type){let content='';if(type==='member')content=`<h2>${t('addMember')}</h2><p>${t('membersSubtitle')}</p><div class="modal-grid"><div class="field"><label>${t('name')}</label><input name="name" required></div><div class="field"><label>${t('document')}</label><input name="id" required></div><div class="field"><label>${t('age')}</label><input name="age" type="number" min="0" required></div><div class="field"><label>${t('sex')}</label><select name="sex"><option>Femenino</option><option>Masculino</option></select></div><div class="field"><label>${t('civil')}</label><select name="civil"><option>Soltero</option><option>Casado</option><option>Unión libre</option><option>No aplica</option></select></div><div class="field"><label>${t('baptism')}</label><select name="baptized"><option value="true">${t('yes')}</option><option value="false">${t('no')}</option></select></div></div>`;else if(type==='movement')content=`<h2>${t('addMovement')}</h2><p>${t('financeSubtitlePastor')}</p><div class="field"><label>${t('description')}</label><input name="description" required></div><div class="modal-grid"><div class="field"><label>${t('income')} / ${t('expenses')}</label><select name="type"><option>${t('income')}</option><option>${t('expenses')}</option></select></div><div class="field"><label>${t('amount')}</label><input name="amount" type="number" min="1" required></div><div class="field"><label>${t('date')}</label><input name="date" type="date" value="2026-06-15"></div></div>`;else if(type==='church')content=`<h2>${t('newChurch')}</h2><p>${t('churchesSubtitle')}</p><div class="field"><label>${t('churchLabel')}</label><input name="name" required></div><div class="field"><label>${t('address')}</label><input name="address" required></div><div class="field"><label>${t('pastorLabel')}</label><input name="pastor"></div>`;else content=`<h2>${type==='teacher'?t('teachersTitle'):t('newPastor')}</h2><p>${t('pastorsSubtitle')}</p><div class="field"><label>${t('name')}</label><input name="name" required></div><div class="field"><label>${t('document')}</label><input name="id"></div><div class="field"><label>${type==='teacher'?t('campuses'):t('academic')}</label><input name="extra"></div>`;$('#modalRoot').innerHTML=`<div class="modal-backdrop"><form class="modal" id="modalForm">${content}<div class="modal-actions"><button type="button" class="secondary" id="cancelModal">${t('cancel')}</button><button class="primary">${t('save')}</button></div></form></div>`;$('#cancelModal').onclick=()=>$('#modalRoot').innerHTML='';$('#modalForm').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(type==='member'){members.unshift({...d,age:Number(d.age),baptized:d.baptized==='true',church:'Iglesia Central'});filter='';notify(t('memberAdded'));if(page==='members'||page==='secretary')renderPage()}else if(type==='movement'){finance.unshift({...d,amount:Number(d.amount)});notify(t('movementAdded'));page='finance';renderPage()}else if(type==='church'){churches.push([d.name,d.address,d.pastor||'Por asignar','0']);notify(t('churchAdded'));page='churches';renderPage()}else{notify(t('save')+' ✓')}$('#modalRoot').innerHTML=''}}
function notify(msg){let n=$('#toast');n.textContent=msg;n.classList.add('show');setTimeout(()=>n.classList.remove('show'),2800)}
function exportData(type){let rows,filename;if(type==='members'){rows=[['Nombre',t('document'),t('age'),t('sex'),t('civil'),t('baptism')],...members.map(m=>[m.name,m.id,m.age,m.sex,m.civil,m.baptized?t('yes'):t('no')])];filename='miembros-circuito.csv'}else if(type==='churches'){rows=[['Iglesia',t('address'),t('pastorLabel'),t('totalMembers')],...churches];filename='iglesias-circuito.csv'}else if(type==='finance'){rows=[['Iglesia',t('initial'),t('income'),t('expenses'),t('final')],...churches.map((c,i)=>[c[0],1800000+i*380000,2450000-i*260000,1130000-i*110000,3120000+i*230000])];filename='informe-financiero.csv'}else{rows=[['Estudiante',t('churchLabel'),t('grades'),t('itaic')],['María Gómez','Iglesia Central','4.6',t('year1')]];filename='itaic-estudiantes.csv'}let csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=filename;a.click();URL.revokeObjectURL(a.href);notify(t('download')+' ✓')}

